package trafficorchestrator

import "encoding/base64"

// These immutable protocol payloads come from the MIT-licensed Flowseal
// zapret-discord-youtube 1.10.2 release. They are embedded in the signed Dropo
// core so the Windows traffic path never reads or downloads bypass assets at
// runtime. Copyright and license text are retained in THIRD_PARTY_NOTICES.md.
var (
	flowseal1102GoogleTLS  = mustDecodeFlowseal1102Payload("")
	flowseal1102GoogleQUIC = mustDecodeFlowseal1102Payload("")
	flowseal1102DiscordUDP = mustDecodeFlowseal1102Payload("")
	flowseal1102STUN       = mustDecodeFlowseal1102Payload("AAEAUCESpEJaS0t1aEd4ZXBuZDAABgAJUUJ6UDp0bldrAAAAwFcABAAAA+eAKgAItrzve7P3KJgAJQAAACQABG4AHv8ACAAUqk+U+R/1zr7f7J5mrdPdm7eV7W6AKAAEKx+2NQ==")
	flowseal1102STUN2      = mustDecodeFlowseal1102Payload("AAEAZCESpELTinHFLpS2D0PpHagABgAMck05WGFRMmtQN1ZjgCIAEEN1c3RvbVNUVU4vMS4wMDEAJAAEaryR44AqAAgXxJti2DWu8QAIABROkyfasWUM+HlC3hasV4M55gt0zQAlAACAVQAEMfeMSoAoAASWLeFz")
	flowseal1102TLS4PDA    = mustDecodeFlowseal1102Payload("")
	flowseal1102TLSMax     = mustDecodeFlowseal1102Payload("")
	flowseal1102TLSSochi   = mustDecodeFlowseal1102Payload("")
)

func mustDecodeFlowseal1102Payload(value string) []byte {
	decoded, err := base64.StdEncoding.DecodeString(value)
	if err != nil {
		panic("invalid embedded Flowseal 1.10.2 payload: " + err.Error())
	}
	return decoded
}
